/* A sixty-second film: 16 seconds of feeling, 24 of discovery, 20 of James Real. */
const JR_FILM=[{"label": "A feeling", "time": 16000, "kicker": "THE WORLD OF JAMES REAL", "kind": "opening", "title": "Some moments<br>become part of us.", "copy": "The warmth of a welcome. The beauty of belonging.", "beats": [["Some moments<br>become part of us.", "The warmth of a welcome. The beauty of belonging."], ["Luxury begins<br>with a feeling.", "Something that moves you. Something unmistakably yours."], ["Make room<br>for a beautiful life.", "Be present. Feel deeply. Let the ordinary become extraordinary."]]}, {"label": "Taste", "time": 4000, "id": "food", "kicker": "01 / TASTE", "title": "Stay for<br>one more moment.", "copy": "The first taste. The shared laughter. The table that brings us home.", "shots": [2, 3]}, {"label": "Style", "time": 4000, "id": "fashion", "kicker": "02 / STYLE", "title": "Wear your<br>own story.", "copy": "Quiet confidence. Beautiful details. The freedom to be yourself.", "shots": [2, 3]}, {"label": "Living", "time": 4000, "id": "living", "kicker": "03 / LIVING", "title": "Come home<br>to yourself.", "copy": "Light, warmth, and a world where you can simply belong.", "shots": [2, 3]}, {"label": "Journey", "time": 4000, "id": "mobility", "kicker": "04 / JOURNEY", "title": "Let wonder<br>lead the way.", "copy": "Beyond the familiar, a new part of you is waiting.", "shots": [5, 0]}, {"label": "Discovery", "time": 4000, "id": "learning", "kicker": "05 / DISCOVERY", "title": "Keep becoming.", "copy": "A new idea. A wider perspective. A life that keeps opening.", "shots": [0, 4]}, {"label": "Leisure", "time": 4000, "id": "leisure", "kicker": "06 / LEISURE", "title": "Give joy<br>your time.", "copy": "Be moved by music. Lost in a moment. Fully alive.", "shots": [2, 5]}, {"label": "James Real", "time": 20000, "kicker": "A LUXURY LIFESTYLE BRAND", "kind": "closing", "copy": "For the pleasure of living.", "beats": [["", "A life rich in feeling."], ["", "Beauty you can feel. Moments you can call your own."], ["", "The luxury of being fully, unmistakably you."], ["", "For the pleasure of living."]]}];
const FILM_TOTAL=JR_FILM.reduce((n,s)=>n+s.time,0);
let introFocus,introFrame,introLast,introElapsed=0,introPaused=false,introIndex=-1;
const film=document.querySelector('#brand-intro');
const FILM_CROPS=['0 0 496 518','510 0 518 518','1040 0 496 518','0 532 496 492','510 532 518 492','1040 532 496 492'];
function filmShot(id,crop,index){return `<svg class="film-photo${index===0?' is-visible':''}" data-film-shot="${index}" viewBox="${FILM_CROPS[crop]}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="assets/${id}-contexts.png" width="1536" height="1024"/></svg>`}
document.querySelector('#film-scenes').innerHTML=JR_FILM.map((s,i)=>`<section class="film-scene ${s.kind||''}" data-film-scene="${i}" aria-hidden="true">${s.id?s.shots.map((crop,j)=>filmShot(s.id,crop,j)).join('')+'<div class="film-shade"></div>':'<div class="film-light"></div><div class="film-gold-beam"></div><div class="film-gold-dust"></div>'}<div class="film-copy">${s.kind==='opening'?'<div class="film-monogram" role="img" aria-label="James Real JR monogram"></div>':''}<p class="film-kicker">${s.kicker}</p>${s.kind==='closing'?'<div class="film-signature film-gold-signature" role="img" aria-label="James Real"></div>':`<h2>${s.title}</h2>`}<p class="film-narrative">${s.copy}</p>${s.kind==='closing'?'<span class="film-six">TASTE · STYLE · LIVING · JOURNEY · DISCOVERY · LEISURE</span>':''}</div></section>`).join('');
document.querySelector('#film-chapters').innerHTML=JR_FILM.map((s,i)=>`<button data-film-go="${i}" aria-label="Go to ${s.label}"><span>${s.label}</span><i></i></button>`).join('');
function filmSeek(index){introElapsed=JR_FILM.slice(0,index).reduce((n,s)=>n+s.time,0);introLast=performance.now();updateFilm()}
function updateFilm(){let accum=0,index=JR_FILM.length-1;for(let i=0;i<JR_FILM.length;i++){accum+=JR_FILM[i].time;if(introElapsed<accum){index=i;break}}if(index!==introIndex){introIndex=index;film.dataset.chapter=String(index);document.querySelectorAll('[data-film-scene]').forEach((el,i)=>{el.classList.toggle('is-active',i===index);el.setAttribute('aria-hidden',String(i!==index))});document.querySelectorAll('[data-film-go]').forEach((el,i)=>{el.classList.toggle('is-current',i===index);el.classList.toggle('is-past',i<index);el.setAttribute('aria-current',i===index?'step':'false')})}const before=JR_FILM.slice(0,index).reduce((n,s)=>n+s.time,0);film.style.setProperty('--chapter-progress',String(Math.max(0,Math.min(1,(introElapsed-before)/JR_FILM[index].time))));const scene=JR_FILM[index],el=film.querySelector(`[data-film-scene="${index}"]`);if(scene.beats){const beat=Math.min(scene.beats.length-1,Math.floor((introElapsed-before)/(scene.time/scene.beats.length)));if(el.dataset.beat!==String(beat)){el.dataset.beat=String(beat);const h=el.querySelector('h2');if(h)h.innerHTML=scene.beats[beat][0];el.querySelector('.film-narrative').textContent=scene.beats[beat][1];}}const shot=Math.min(1,Math.floor((introElapsed-before)/(JR_FILM[index].time/2)));film.querySelectorAll(`[data-film-scene="${index}"] [data-film-shot]`).forEach(el=>el.classList.toggle('is-visible',Number(el.dataset.filmShot)===shot));document.querySelector('#film-clock').textContent=`${String(Math.floor(introElapsed/1000)).padStart(2,'0')} / ${Math.round(FILM_TOTAL/1000)}`;}
function filmTick(now){if(film.hidden)return;if(!introPaused)introElapsed+=Math.max(0,(now-introLast));introLast=now;updateFilm();if(introElapsed>=FILM_TOTAL){finishIntro();return}introFrame=requestAnimationFrame(filmTick)}
function finishIntro(){try{sessionStorage.setItem('jr-film-seen','1')}catch{}cancelAnimationFrame(introFrame);film.hidden=true;document.querySelector('.site-chrome').inert=false;main.inert=false;document.querySelector('footer').inert=false;document.body.classList.remove('intro-open');introFocus?.focus({preventScroll:true})}
function playIntro(){introFocus=document.activeElement;film.hidden=false;document.body.classList.add('intro-open');document.querySelector('.site-chrome').inert=true;main.inert=true;document.querySelector('footer').inert=true;introElapsed=0;introIndex=-1;introPaused=false;film.classList.remove('is-paused');document.querySelector('#intro-pause').textContent='Pause';document.querySelector('#intro-pause').setAttribute('aria-pressed','false');if(matchMedia('(prefers-reduced-motion: reduce)').matches)introElapsed=FILM_TOTAL-JR_FILM.at(-1).time;updateFilm();document.querySelector('#intro-skip').focus();cancelAnimationFrame(introFrame);introLast=performance.now();introFrame=requestAnimationFrame(filmTick)}
document.querySelector('#intro-skip').onclick=finishIntro;
document.querySelector('#replay-intro').onclick=playIntro;
document.querySelector('#intro-pause').onclick=()=>{introPaused=!introPaused;film.classList.toggle('is-paused',introPaused);document.querySelector('#intro-pause').textContent=introPaused?'Play':'Pause';document.querySelector('#intro-pause').setAttribute('aria-pressed',String(introPaused))};
document.querySelector('#film-chapters').addEventListener('click',e=>{const b=e.target.closest('[data-film-go]');if(b)filmSeek(Number(b.dataset.filmGo))});
document.addEventListener('keydown',e=>{if(film.hidden)return;if(e.key==='Escape')finishIntro();if(e.key==='Tab'){const controls=[...film.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus()}}});
document.addEventListener('visibilitychange',()=>{introLast=performance.now()});
let filmSeen=false;try{filmSeen=sessionStorage.getItem('jr-film-seen')==='1'}catch{}if((location.hash||'#home')==='#home'&&!filmSeen&&!matchMedia('(prefers-reduced-motion: reduce)').matches)playIntro();

window.addEventListener('hashchange',()=>{if(!film.hidden&&location.hash!=='#home')finishIntro()});
